/* SHA-256 so passwords are not stored as plain text */
function sha256(str) {
  const K = [], H = []; let p = 2, n = 0;
  const isP = (x) => { for (let f = 2; f * f <= x; f++) if (x % f === 0) return false; return true; };
  const fr = (x) => ((x - Math.floor(x)) * 4294967296) | 0;
  while (n < 64) { if (isP(p)) { if (n < 8) H[n] = fr(Math.pow(p, 1 / 2)); K[n] = fr(Math.pow(p, 1 / 3)); n++; } p++; }
  const bytes = new TextEncoder().encode(str), l = bytes.length;
  const buf = new Uint8Array(((l + 9 + 63) >> 6) << 6); buf.set(bytes); buf[l] = 0x80;
  const dv = new DataView(buf.buffer); const bits = l * 8;
  dv.setUint32(buf.length - 4, bits >>> 0); dv.setUint32(buf.length - 8, Math.floor(bits / 4294967296));
  const h = H.slice(), w = new Array(64);
  for (let i = 0; i < buf.length; i += 64) {
    for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4) | 0;
    for (let j = 16; j < 64; j++) {
      const a = w[j - 15], b = w[j - 2];
      const s0 = ((a >>> 7) | (a << 25)) ^ ((a >>> 18) | (a << 14)) ^ (a >>> 3);
      const s1 = ((b >>> 17) | (b << 15)) ^ ((b >>> 19) | (b << 13)) ^ (b >>> 10);
      w[j] = (w[j - 16] + s0 + w[j - 7] + s1) | 0;
    }
    let [A, B, C, D, E, F, G, X] = h;
    for (let j = 0; j < 64; j++) {
      const S1 = ((E >>> 6) | (E << 26)) ^ ((E >>> 11) | (E << 21)) ^ ((E >>> 25) | (E << 7));
      const t1 = (X + S1 + ((E & F) ^ (~E & G)) + K[j] + w[j]) | 0;
      const S0 = ((A >>> 2) | (A << 30)) ^ ((A >>> 13) | (A << 19)) ^ ((A >>> 22) | (A << 10));
      const t2 = (S0 + ((A & B) ^ (A & C) ^ (B & C))) | 0;
      X = G; G = F; F = E; E = (D + t1) | 0; D = C; C = B; B = A; A = (t1 + t2) | 0;
    }
    h[0] = (h[0] + A) | 0; h[1] = (h[1] + B) | 0; h[2] = (h[2] + C) | 0; h[3] = (h[3] + D) | 0;
    h[4] = (h[4] + E) | 0; h[5] = (h[5] + F) | 0; h[6] = (h[6] + G) | 0; h[7] = (h[7] + X) | 0;
  }
  return h.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}
const hashPw = (salt, pw) => { let h = salt + ':' + pw; for (let i = 0; i < 400; i++) h = sha256(salt + h); return h; };

