  const [page, arg] = path.split('/');
  R.page = page || 'home'; R.arg = arg || ''; R.q = new URLSearchParams(query || '');
  if (!(VIEWS[R.page] || REACT_PAGES.has(R.page)) || !pageAllowed(R.page)) { R.page = 'home'; R.arg = ''; R.q = new URLSearchParams(); }
