/* ---------------------------------------------------------------- approvals */
function pendingForMe() {
  if (!me) return [];
  const out = [];
  S.leaveReqs.filter(leaveApproverOK).forEach((r) => out.push({ kind: 'leave', r }));
  S.regs.filter((r) => r.status === 'pending' && regApproverOK(r)).forEach((r) => out.push({ kind: 'reg', r }));
  S.goals.filter((g) => g.status === 'submitted' && (empById(g.empId) || {}).managerId === me.id).reduce((m, g) => (m.has(g.empId + g.cycleId) ? m : m.set(g.empId + g.cycleId, g)), new Map()).forEach((g) => out.push({ kind: 'goals', r: g }));
  S.exits.forEach((x) => { const e = empById(x.empId); if (!e || e.id === me.id) return;
    if (x.status === 'requested' && (e.managerId === me.id || (isHR(x.companyId) && !empById(e.managerId)))) out.push({ kind: 'exit', r: x, what: 'Resignation to accept', link: '#/exit/' + x.id });
    else if (x.status === 'hr' && isHR(x.companyId)) out.push({ kind: 'exit', r: x, what: 'Resignation for HR acceptance', link: '#/exit/' + x.id });
    else if (x.status === 'notice') {
      x.clearances.filter((c) => c.status !== 'cleared' && clearOwnerOK(x, c) && (c.owner !== 'hr' || isHR(x.companyId))).forEach((c) => out.push({ kind: 'exit', r: x, what: `${c.dept} clearance`, link: '#/exit/' + x.id }));
      if (isHR(x.companyId) && clearancesDone(x) && x.fnf.status === 'pending') out.push({ kind: 'exit', r: x, what: 'Full and final to approve', link: '#/exit/' + x.id });
    } });
  { const t = todayISO(), from = `${ymAdd(t.slice(0, 7), -1)}-01`; const mineE = S.employees.filter((e) => active(e) && otEligibleOf(e) && e.id !== me.id && (e.managerId === me.id || (isHR(e.companyId) && !empById(e.managerId))));
    const det = otDetectedPending(mineE, from, t); const pend = S.otRecs.filter((x) => x.status === 'pending' && mineE.some((e) => e.id === x.empId));
    const by = {}; det.concat(pend.map((x) => ({ empId: x.empId, hrs: x.requestedHrs || 0 }))).forEach((x) => { by[x.empId] = by[x.empId] || { days: 0, hrs: 0 }; by[x.empId].days++; by[x.empId].hrs += +x.hrs || 0; });
    Object.entries(by).forEach(([id, v]) => out.push({ kind: 'ot', r: { empId: id }, what: `Overtime to approve: ${v.days} day${v.days > 1 ? 's' : ''}, ${num(v.hrs, 1)} h`, link: `#/overtime?emp=${id}&m=${t.slice(0, 7)}` })); }
  S.reqs.filter((q) => q.status === 'pending' && isHR(q.companyId) && q.createdBy !== me.id).forEach((q) => out.push({ kind: 'req', r: { ...q, empId: q.createdBy }, what: `Job requisition ${q.no}: ${q.title}`, link: '#/req/' + q.id }));
  S.apps.filter(offerApproverOK).forEach((a) => out.push({ kind: 'offer', r: { empId: null, cand: candById(a.candId).name, ctc: a.offer.ctc }, what: `Offer approval, ${a.offer.approvals.find((x) => !x.decision).label}`, link: '#/app/' + a.id }));
  extPending().forEach((x) => out.push(x));
  S.interviews.filter((i) => (i.panel || []).includes(me.id) && !(i.feedback || {})[me.id] && i.status !== 'cancelled' && i.status !== 'noshow' && i.date <= todayISO()).forEach((i) => out.push({ kind: 'fb', r: { cand: candById(appById(i.appId).candId).name }, what: `Interview feedback, ${i.round}`, link: '#/app/' + i.appId }));
  return out;
}
function regApproverOK(r) { const e = empById(r.empId); if (r.steps) return !!e && canDecide({ ...r, companyId: e.companyId }); return e && ((e.managerId === me.id) || (isHR(e.companyId) && (!e.managerId || !empById(e.managerId))) ) && e.id !== me.id; }

