    if (extra) { $('#ee').textContent = extra; return; }
    const miss = fields.find((f) => f.req && !d[f.k]); if (miss) { $('#ee').textContent = `Enter ${miss.label.toLowerCase()}.`; return; }
    if (d.email && S.employees.some((x) => x.id !== e.id && (x.email || '').toLowerCase() === d.email.toLowerCase())) { $('#ee').textContent = 'Another employee has this e-mail.'; return; }
    if (d.empNo && S.employees.some((x) => x.id !== e.id && x.companyId === e.companyId && x.empNo === d.empNo)) { $('#ee').textContent = 'That employee number is in use.'; return; }
    if (d.pan && !/^[A-Z]{5}\d{4}[A-Z]$/.test(d.pan.toUpperCase())) { $('#ee').textContent = 'PAN should look like ABCDE1234F.'; return; }
    if (d.ifsc && !/^[A-Z]{4}0[A-Z0-9]{6}$/.test(d.ifsc.toUpperCase())) { $('#ee').textContent = 'IFSC should look like HDFC0001234.'; return; }
    if (d.aadhaar && !/^\d{12}$/.test(d.aadhaar.replace(/\s/g, ''))) { $('#ee').textContent = 'Aadhaar has 12 digits.'; return; }
    if (d.uan && !/^\d{12}$/.test(d.uan)) { $('#ee').textContent = 'UAN has 12 digits.'; return; }
    if (d.esiNo && !/^\d{10}$/.test(d.esiNo)) { $('#ee').textContent = 'The ESI IP number has 10 digits.'; return; }
    if (d.managerId === e.id || (d.managerId && allReportees(e.id).includes(d.managerId))) { $('#ee').textContent = 'That manager reports to this employee.'; return; }
    if (d.pan) d.pan = d.pan.toUpperCase(); if (d.ifsc) d.ifsc = d.ifsc.toUpperCase(); if (d.aadhaar) d.aadhaar = d.aadhaar.replace(/\s/g, '');
    const changed = fields.filter((f) => String(e[f.k] ?? '') !== String(d[f.k] ?? '')).map((f) => f.label);
    Object.assign(e, d);
    if (changed.length) (e.history = e.history || []).push({ date: todayISO(), type: `${tab[0].toUpperCase() + tab.slice(1)} details changed`, note: changed.join(', '), by: me.id });
