function getPosition(timeout = 10000) {
  return new Promise((res, rej) => {
    if (!navigator.geolocation) return rej(new Error('This browser cannot share its location.'));
    navigator.geolocation.getCurrentPosition((p) => res({ lat: +p.coords.latitude.toFixed(6), lng: +p.coords.longitude.toFixed(6), acc: Math.round(p.coords.accuracy) }),
      (e) => rej(new Error(e.code === 1 ? 'Location permission was refused.' : 'Location is not available.')), { enableHighAccuracy: true, timeout, maximumAge: 30000 });
  });
}
ACT.punch = async (b) => {
  const t = todayISO(); const co = coById(me.companyId);
  let p = punchOf(me.id, t);
  if (p && p.out) { toast('You have already punched out today'); return; }
  b.disabled = true;
  let pos = null;
  try { pos = await getPosition(); } catch (e) { if (co.punchNeedsLocation) { toast(e.message + ' Punching needs your location.'); b.disabled = false; return; } }
  if (!p) { p = { id: uid(), empId: me.id, date: t, in: Date.now(), out: null, inLoc: pos, source: 'web' }; S.punches.push(p);
    const sf = shiftFor(me, t); const late = sf.shift ? Math.round((p.in - tsAt(t, sf.shift.start)) / 60000) - (+sf.shift.graceIn || 0) : 0;
    toast(`Punched in at ${hm(p.in)}${late > 0 ? `, ${late} minutes late` : ''}`); }
  else { p.out = Date.now(); p.outLoc = pos; toast(`Punched out at ${hm(p.out)}, ${num((p.out - p.in) / 3600000, 1)} hours`); }
  saveNow(); route();
};
const ST_LABEL = { P: 'Present', HD: 'Half day', A: 'Absent', L: 'Leave', H: 'Holiday', WO: 'Weekly off' };
function monthGrid(emp, ym, clickAct) {
  const first = D(`${ym}-01`); const lead = (first.getDay() + 6) % 7; const days = daysInMonth(ym); const t = todayISO();
  let cells = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((d) => `<div class="h">${d}</div>`).join('') + '<div class="d x"></div>'.repeat(lead);
  for (let i = 1; i <= days; i++) {
    const iso = `${ym}-${pad(i)}`; const s = dayStatus(emp, iso);
    const lv = s.leave ? ltById(s.leave.typeId) : null;
    cells += `<button class="d ${iso === t ? 'today' : ''}" data-act="${clickAct}" data-d="${iso}" data-emp="${emp.id}"><b>${i}</b>
      ${s.code ? `<div><span class="st ${s.code}">${s.code === 'L' && lv ? esc(lv.code) : esc(s.code)}</span>${s.late > 0 ? '<span class="st LT">Late</span>' : ''}${s.missingOut ? '<span class="st LT">No out</span>' : ''}</div>` : ''}
      ${s.punch && s.punch.in ? `<div class="fine">${hm(s.punch.in)}–${hm(s.punch.out)}</div>` : s.holiday ? `<div class="fine">${esc(s.holiday.name)}</div>` : ''}</button>`;
  }
  return `<div class="cal">${cells}</div>`;
}
