      validate: (d) => { const map = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 }; d.weeklyOff = (d.weeklyOffTxt || '').split(/[,\s]+/).filter(Boolean).map((x) => map[x.slice(0, 3).toLowerCase()]).filter((x) => x !== undefined); d.night = toMin(d.end) <= toMin(d.start); return +d.halfDayHrs > +d.fullDayHrs ? 'Half-day hours cannot exceed full-day hours.' : ''; },
