ACT.punchImport = () => {
  openDlg(`<div class="dlg"><h2>Import biometric punches</h2><p class="mut" style="margin:0">An Excel or CSV export from the attendance device with columns <b>Employee number</b>, <b>Date</b> and <b>Time</b> (one row per punch). The first punch of a day is the time in and the last is the time out. Existing punches for those days are replaced.</p>
    <input type="file" class="inp" id="piFile" accept=".xlsx,.xls,.csv"><p class="err" id="pie"></p><div class="btns"><button class="btn ghost" data-act="close">Cancel</button><button class="btn pri" data-act="punchImportGo">Import</button></div></div>`);
};
ACT.punchImportGo = async () => {
  const f = $('#piFile').files[0]; if (!f) { $('#pie').textContent = 'Choose a file.'; return; }
  try {
    const rows = await readSheet(f); const groups = {}; let bad = 0;
    const key = (r, names) => { const k = Object.keys(r).find((x) => names.some((n) => x.toLowerCase().replace(/[^a-z]/g, '') === n)); return k ? r[k] : ''; };
    rows.forEach((r) => {
      const no = String(key(r, ['employeenumber', 'empno', 'employeeid', 'employeecode', 'code'])).trim();
      let d = String(key(r, ['date', 'punchdate'])).trim(); const t = String(key(r, ['time', 'punchtime'])).trim();
      const e = S.employees.find((x) => x.companyId === CO && x.empNo === no);
      const m = d.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2,4})$/); if (m) d = `${m[3].length === 2 ? '20' + m[3] : m[3]}-${pad(m[2])}-${pad(m[1])}`;
      const tm = t.match(/(\d{1,2}):(\d{2})/);
      if (!e || !/^\d{4}-\d{2}-\d{2}$/.test(d) || !tm) { bad++; return; }
      (groups[e.id + '|' + d] = groups[e.id + '|' + d] || []).push(`${pad(tm[1])}:${tm[2]}`);
    });
    Object.entries(groups).forEach(([k, times]) => { const [id, d] = k.split('|'); times.sort(); setPunch(id, d, times[0], times.length > 1 ? times[times.length - 1] : '', 'device'); });
    saveNow(); closeDlg(); toast(`${Object.keys(groups).length} days imported${bad ? `, ${bad} rows skipped` : ''}`); route();
  } catch (e) { $('#pie').textContent = e.message; }
};

