/* ---------------------------------------------------------------- common */
const hrIdsOf = (coId) => S.employees.filter((e) => active(e) && (e.role === 'super' || (e.role === 'hr' && (e.companyId === coId || (e.hrCompanies || []).includes(coId))))).map((e) => e.id);
