  if (!(await confirmBox('Post variable pay?', `Amounts go to ${monthName(month)} payroll as Variable pay.`, 'Post'))) return;
  ensureComp(co.id, '1550', 'Variable pay', { variable: true });
  let n = 0, total = 0;
