    S.payInputs.push({ id: uid(), companyId: co.id, empId: e.id, month, code: '1550', amount: c.amount, note: `Variable pay ${monthName(start)}${months > 1 ? ' to ' + monthName(ymAdd(start, months - 1)) : ''}, ${c.pct}%`, varKey: key, varPct: c.pct });
